use eframe::egui::{self,Color32,Painter,Pos2,Rect,Stroke,Vec2};
#[derive(Clone,Copy,Debug)]pub enum Icon{Home,Sessions,All,Diffs,Same,Context,Minor,Rules,Format,Copy,Next,Prev,Swap,Reload,Expand,Collapse,Select,Files,Refresh,Stop,Filters,Sync,CopyLeft,CopyRight,Edit,Structure,Folder,File,ArrowLeft,ArrowRight,Status}
pub fn paint(p:&Painter,rect:Rect,icon:Icon){let c=Color32::from_rgb(45,91,145);let mid=rect.center();match icon{Icon::Home=>{p.rect_stroke(rect.shrink(4.0),0.0,Stroke::new(1.5,c),egui::epaint::StrokeKind::Inside);p.line_segment([Pos2::new(rect.left()+3.0,mid.y),Pos2::new(mid.x,rect.top()+3.0)],Stroke::new(1.5,c));},Icon::ArrowLeft|Icon::ArrowRight=>{let x=if matches!(icon,Icon::ArrowLeft){-1.0}else{1.0};p.line_segment([mid-Vec2::new(7.0*x,0.0),mid+Vec2::new(7.0*x,0.0)],Stroke::new(2.0,c));},_=>{p.circle_stroke(mid,rect.width().min(rect.height())*0.28,Stroke::new(1.5,c));p.text(mid,egui::Align2::CENTER_CENTER,"✦",egui::FontId::proportional(12.0),c);}}}
